import { FETCH_ALL, CREATE, UPDATE, DELETE, LIKE } from '../constants/actionTypes';

export default (emotes = [], action) => {
  switch (action.type) {
    case FETCH_ALL:
      return action.payload;
    case LIKE:
      return emotes.map((emote) => (emote._id === action.payload._id ? action.payload : emote));
    case CREATE:
      return [...emotes, action.payload];
    case UPDATE:
      return emotes.map((emote) => (emote._id === action.payload._id ? action.payload : emote));
    case DELETE:
      return emotes.filter((emote) => emote._id !== action.payload);
    default:
      return emotes;
  }
};

