import React, { useEffect } from 'react';
import { Button, Typography } from '@material-ui/core';
import { Link } from 'react-router-dom';
import { useDispatch, useSelector } from 'react-redux';
import { useParams } from "react-router-dom";
import classNames from 'classnames';
import moment from 'moment';

import User from '../User/User';

import ThumbUpAltIcon from '@material-ui/icons/ThumbUpAlt';
import ThumbUpAltOutlined from '@material-ui/icons/ThumbUpAltOutlined';


import { getEmote, likeEmote } from '../../../actions/emotes';
import { HOSTURL } from '../../../api/index';
import useStyles from './styles';

const EmoteData = () => {

  const dispatch = useDispatch();
  const classes = useStyles();
  const user = JSON.parse(localStorage.getItem('profile'));

	const emote = useSelector((state) => state.emote);
  const {id} = useParams();

	useEffect(() => {
    dispatch(getEmote(id)); // eslint-disable-next-line
  }, [dispatch]);


  const Likes = () => {
    if (emote?.likes?.length > 0) {

      return emote.likes.find((like) => like === user?.result?.id)
        ? (
          <><ThumbUpAltIcon fontSize="small" />&nbsp;{emote.likes.length > 2 ? `You and ${emote.likes.length - 1} others` : `${emote.likes.length} like${emote.likes.length > 1 ? 's' : ''}` }</>
        ) : (
          <><ThumbUpAltOutlined fontSize="small" />&nbsp;{emote.likes.length} {emote.likes.length === 1 ? 'Like' : 'Likes'}</>
        );
    }

    return <><ThumbUpAltOutlined fontSize="small" />&nbsp;Like</>;
  };

  return (
    <div className={classes.col}>
      <div className={classNames(classes.card, classes.m_1, classes.p_0)}>
        <div className={classNames(classes.alignItemsCenter, classes.cardHeader, classes.dFlex, classes.justifyContentBetween, classes.p_2, classes.pxLg_3)}>
          <h3 className={classes.h3} style={{marginBottom: '0px'}}> {emote.code} </h3>
          <p className={classes.p} style={{marginBottom: '0px'}}> Загружено <Typography component={Link} to={"/users/" + emote.user?._id}> {emote.user?.user_login} </Typography> {moment(emote.createdAt).fromNow()} </p>
        </div>
        <div className={classNames(classes.alignItemsCenter, classes.cardBody, classes.dFlex, classes.alignSelfCenter, classes.justifyContentCenter)}>
          <img className={classes.m_2} width={28} height={28} src={HOSTURL + 'cached/emote/' + emote._id + '/1x'} alt={emote.code}/>
          <img className={classes.m_2} width={64} height={64} src={HOSTURL + 'cached/emote/' + emote._id + '/2x'} alt={emote.code}/>
          <img className={classes.m_2} width={128} height={128} src={HOSTURL + 'cached/emote/' + emote._id + '/3x'} alt={emote.code}/>
        </div>
        <div className={classes.cardFooter}>
          <Button size="small" color="primary" disabled={!user?.result || user?.result?.id === emote?.user?._id || !emote.sharing} onClick={() => dispatch(likeEmote(emote._id))}>
	          <Likes />
	        </Button>
        </div>
      </div>
      <div className={classNames(classes.card, classes.m_1, classes.p_0)}>
        <div className={classNames(classes.alignItemsCenter, classes.cardHeader, classes.dFlex, classes.justifyContentBetween, classes.p_2, classes.pxLg_3)}>
            <h3 className={classes.h3} style={{marginBottom: '0px'}}> Каналы ({emote.likes?.length}) </h3>
        </div>
        <div className={classNames(classes.alignItemsCenter, classes.cardBody, classes.dFlex, classes.alignSelfCenter, classes.w_100, classes.dInlineFlex, classes.flexWrap)}>
					{typeof emote.likes != 'undefined' ? emote.likes.map((u, index) => <User key={index} u={u} /> ) : ''}
        </div>
      </div>
    </div>
	);
};

export default EmoteData;
