import React from 'react';
import { Container } from '@material-ui/core';
import { Switch, Route, HashRouter  } from 'react-router-dom';

import Home from './components/Home/Home';
import Navbar from './components/Navbar/Navbar';
import Auth from './components/Auth/Auth';
import Emote from './components/Emote/Emote';
import User from './components/User/User';
import Dashboard from './components/Dashboard/Dashboard';
import Global from './components/Global/Global';

const App = () => (
  <HashRouter>
    <Container maxWidth="lg">
      <Navbar />
      <Switch>
        <Route path="/" exact component={Home} />
        <Route path="/auth" exact component={Auth} />
        <Route path="/emotes/global" exact component={Global} />
        <Route path="/emotes/:id" exact component={Emote} />
        <Route path="/users/:id" exact component={User} />
        <Route path="/dashboard/:tag" exact component={Dashboard} />
        <Route path='*' component={<div>NotFound</div>} />
      </Switch>
    </Container>
  </HashRouter>
);

export default App;
