import React from 'react';
import { CircularProgress } from '@material-ui/core';
import { useSelector } from 'react-redux';
import classNames from 'classnames';
import Emote from '../../User/Emote/Emote';
import useStyles from './styles';

console.log('e')

const Emotes = ({ setCurrentId }) => {
  // const emotes = useSelector((state) => state.emotes);
  const classes = useStyles();

	const emote = useSelector((state) => state.user);
	console.log(emote)
  return (
  	!emote?.user ? <CircularProgress /> : (
			<div className={classes.row}>
				<div className={classes.col}>
			        <div className={classNames(classes.card, classes.m_1, classes.p_0)}>
				        <div className={classNames(classes.alignItemsCenter, classes.cardHeader, classes.dFlex, classes.justifyContentBetween, classes.p_2, classes.pxLg_3)}>
			            	<h3 className={classes.h3} style={{marginBottom: '0px'}}> Эмоции канала ({emote.user?.length}/{emote.limitCreator}) </h3>
			        	</div>
			        	<div className={classNames(classes.alignItemsCenter, classes.cardBody, classes.dFlex, classes.alignSelfCenter, classes.w_100, classes.dInlineFlex, classes.flexWrap)}>
			        	{typeof emote.user == 'object' ? 
				        	emote.user.map((emote) => (
					          <Emote key={emote._id} emote={emote} setCurrentId={setCurrentId} />
					        )) : ''}
					    </div>
			        </div>
			        <div className={classNames(classes.card, classes.m_1, classes.p_0)}>
				        <div className={classNames(classes.alignItemsCenter, classes.cardHeader, classes.dFlex, classes.justifyContentBetween, classes.p_2, classes.pxLg_3)}>
			            	<h3 className={classes.h3} style={{marginBottom: '0px'}}> Общие эмоции ({emote.likes?.length}/{emote.limitLike}) </h3>
			        	</div>
						<div className={classNames(classes.alignItemsCenter, classes.cardBody, classes.dFlex, classes.alignSelfCenter, classes.w_100, classes.dInlineFlex, classes.flexWrap)}>
						{typeof emote.likes == 'object' ? 
				        	emote.likes.map((emote) => (
					          <Emote key={emote._id} emote={emote} setCurrentId={setCurrentId} />
					        )) : ''}
						</div>
			        </div>
				</div>
			</div>
		)
  );
};

export default Emotes;
