import React from 'react';
import { Typography } from '@material-ui/core/';
import { Link } from 'react-router-dom';

import { HOSTURL } from '../../../api/index';

import useStyles from './styles';

const Emote = ({ emote, setCurrentId }) => {
  const classes = useStyles();

	console.log(emote)
	const url = "/emotes/" + emote._id

  return (
  	<div className={classes.div_emoteCard}>
  		<Typography component={Link} to={url} className={classes.emoteCard}>
	      <img className={classes.img} width={56} height={56} src={HOSTURL + 'cached/emote/' + emote._id + '/2x'} alt={emote.code} />
	      <div className={classes.div}><span className={classes.span}> {emote.code} </span></div>
		  </Typography>
		</div>
  );
};

export default Emote;
