import React, { useEffect } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { useParams } from "react-router-dom";
import classNames from 'classnames';
import { CircularProgress } from '@material-ui/core';


import { getUserEmotes } from '../../actions/emotes';
import useStyles from './styles';

import Emote from './Emote/Emote';

const User = () => {

	const dispatch = useDispatch();
	const classes = useStyles();
	// const user = JSON.parse(localStorage.getItem('profile'));

	const emotes = useSelector((state) => state.user);
	const {id} = useParams();

	useEffect(() => {
		dispatch(getUserEmotes(id));
	}, [dispatch, id]);

	console.log(emotes)


	const setCurrentId = (id) => {
		console.log('setCurrentId', id)
	}


	return (
		!emotes?.likes ? <CircularProgress /> : (
			<div className={classes.row}>
				<div className={classes.col}>
	        <div className={classNames(classes.card, classes.m_1, classes.p_0)}>
		        <div className={classNames(classes.alignItemsCenter, classes.cardHeader, classes.dFlex, classes.justifyContentBetween, classes.p_2, classes.pxLg_3)}>
            	<h3 className={classes.h3} style={{marginBottom: '0px'}}> Эмоции канала ({emotes.user?.length}/{emotes.limitCreator}) </h3>
	        	</div>
	        	<div className={classNames(classes.alignItemsCenter, classes.cardBody, classes.dFlex, classes.alignSelfCenter, classes.w_100, classes.dInlineFlex, classes.flexWrap)}>
		        	{emotes.user.map((emote) => (
			          <Emote key={emote._id} emote={emote} setCurrentId={setCurrentId} />
			        ))}
				    </div>
	        </div>
	        <div className={classNames(classes.card, classes.m_1, classes.p_0)}>
		        <div className={classNames(classes.alignItemsCenter, classes.cardHeader, classes.dFlex, classes.justifyContentBetween, classes.p_2, classes.pxLg_3)}>
	            <h3 className={classes.h3} style={{marginBottom: '0px'}}> Общие эмоции ({emotes.likes?.length}/{emotes.limitLike}) </h3>
	        	</div>
						<div className={classNames(classes.alignItemsCenter, classes.cardBody, classes.dFlex, classes.alignSelfCenter, classes.w_100, classes.dInlineFlex, classes.flexWrap)}>
							{emotes.likes.map((emote) => (
								<Emote key={emote._id} emote={emote} setCurrentId={setCurrentId} />
							))}
						</div>
		      </div>
				</div>
			</div>
		)
	);
};

export default User;
