import React, { useState, useEffect } from 'react';
import { TextField, Button, Typography, Paper, Checkbox, FormControlLabel } from '@material-ui/core';
import { useDispatch, useSelector } from 'react-redux';
import { useParams } from "react-router-dom";
// import FileBase from 'react-file-base64';
import classNames from 'classnames';

import { updateEmote, deleteEmote } from '../../../actions/emotes';
import useStyles from './styles';

const Form = () => {
	
	const emote = useSelector((state) => state.emote);
	console.log(emote)

  const [emoteData, setEmoteData] = useState({ code: '', message: '', selectedFile: '', sharing: true });
  // const emote = useSelector((state) => (id ? state.emotes.find((message) => message._id === id) : null));
  const dispatch = useDispatch();
  const classes = useStyles();
  // const user = JSON.parse(localStorage.getItem('profile'));

  useEffect(() => {
    setEmoteData(emote); // eslint-disable-next-line
  }, [dispatch]);

  // const clear = () => {
  //   setid(0);
  //   setEmoteData({ code: '', message: '', selectedFile: '' });
  // };
  const {id} = useParams();

  const handleSubmit = async (e) => {
    e.preventDefault();
		dispatch(updateEmote(id, { ...emoteData }));
  };

  const remove = () => {
  	dispatch(deleteEmote(id));
  }

  if (!emote) return ('')
  return (
    <Paper className={classNames(classes.paper, classes.width_25p)}>
      <form autoComplete="off" noValidate className={`${classes.root} ${classes.form}`} onSubmit={handleSubmit}>
        <Typography variant="h6">{id ? `Редактирование "${emote.code}"` : 'Создание эмоции'}</Typography>
        <TextField name="code" variant="outlined" label="Заголовок" fullWidth value={emoteData.code} onChange={(e) => setEmoteData({ ...emoteData, code: e.target.value })} />
        <TextField name="message" variant="outlined" label="Сообщение" fullWidth multiline rows={4} value={emoteData.message} onChange={(e) => setEmoteData({ ...emoteData, message: e.target.value })} />
        <FormControlLabel control={<Checkbox checked={emoteData.sharing} onChange={(e) => setEmoteData({ ...emoteData, sharing: e.target.checked })} />} label="Совместное использование" />
        <Button className={classes.buttonSubmit} variant="contained" color="primary" size="large" type="submit" fullWidth>Отправить</Button>
        <Button variant="contained" color="secondary" size="small" onClick={remove} fullWidth>Удалить</Button>
      </form>
    </Paper>
  );
};

export default Form;
