import React, { useState, useEffect } from 'react';
import { TextField, Button, Typography, Paper, FormControlLabel, Checkbox } from '@material-ui/core';
import { useDispatch, useSelector } from 'react-redux';
import FileBase from 'react-file-base64';

import { createEmote, updateEmote } from '../../actions/emotes';
import useStyles from './styles';

const Form = ({ currentId, setCurrentId }) => {
  const [emoteData, setEmoteData] = useState({ code: '', message: '', selectedFile: '', sharing: true });
  const emote = useSelector((state) => (currentId ? state.emotes.find((message) => message._id === currentId) : null));
  const dispatch = useDispatch();
  const classes = useStyles();
  const user = JSON.parse(localStorage.getItem('profile'));

  console.log(user)

  useEffect(() => {
    if (emote) setEmoteData(emote);
  }, [emote]);

  const clear = () => {
    setCurrentId(0);
    setEmoteData({ code: '', message: '', selectedFile: '', sharing: true });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (currentId === 0) {
      dispatch(createEmote({ ...emoteData }));
      clear();
    } else {
      dispatch(updateEmote(currentId, { ...emoteData }));
      clear();
    }
  };

  if (!user?.result?.user_login) {
    return (
      <Paper className={classes.paper}>
        <Typography variant="h6" align="center">
          Пожалуйста, войдите в систему, чтобы создавать свои собственные эмоции и ставить лайки другим.
        </Typography>
      </Paper>
    );
  }

  return (
    <Paper className={classes.paper}>
      <form autoComplete="off" noValidate className={`${classes.root} ${classes.form}`} onSubmit={handleSubmit}>
        <Typography variant="h6">{currentId ? `Редактирование "${emote.code}"` : 'Создание эмоции'}</Typography>
        <TextField name="title" variant="outlined" label="Заголовок" fullWidth value={emoteData.code} onChange={(e) => setEmoteData({ ...emoteData, code: e.target.value })} />
        <TextField name="message" variant="outlined" label="Сообщение" fullWidth multiline rows={4} value={emoteData.message} onChange={(e) => setEmoteData({ ...emoteData, message: e.target.value })} />
        <div className={classes.fileInput}><FileBase type="file" multiple={false} onDone={({ base64 }) => setEmoteData({ ...emoteData, selectedFile: base64 })} /></div>
        <FormControlLabel control={<Checkbox checked={emoteData.sharing} onChange={(e) => setEmoteData({ ...emoteData, sharing: e.target.checked })} />} label="Совместное использование" />
        <Button className={classes.buttonSubmit} variant="contained" color="primary" size="large" type="submit" fullWidth>Отправить</Button>
        <Button variant="contained" color="secondary" size="small" onClick={clear} fullWidth>Удалить</Button>
      </form>
    </Paper>
  );
};

export default Form;
