export const confirmationwasd = (formData, router) => async (dispatch) => {
  try {
    const { data } = await api.confirmationwasd(formData);

    console.log(data)

    dispatch({ type: AUTH, data });

    const decodedToken = decode(data.token);

    localStorage.setItem('profile', JSON.stringify({ result: decodedToken, token: data.token }));

    router.push('/');
  } catch (error) {
    console.log(error);
  }
};