import axios from 'axios';

// "http://localhost:5000/"
export const HOSTURL = "https://radiant-basin-27885.herokuapp.com/"
const API = axios.create({ baseURL: HOSTURL + "api/v1/" });

API.interceptors.request.use((req) => {
  if (localStorage.getItem('profile')) {
    console.log(localStorage.getItem('profile'))
    req.headers.Authorization = `Bearer ${JSON.parse(localStorage.getItem('profile')).token}`;
  }

  return req;
});

export const fetchEmotes = () => API.get('/posts');
export const createEmote = (newEmote) => API.post('/posts', newEmote);
export const likeEmote = (id) => API.patch(`/posts/${id}/likePost`);
export const updateEmote = (id, updatedEmote) => API.patch(`/posts/${id}`, updatedEmote);
export const deleteEmote = (id) => API.delete(`/posts/${id}`);
export const getEmote = (id) => API.get(`/posts/${id}`);
export const getUserEmotes = (id) => API.get(`/posts/user/${id}`);
export const getGlobalEmotes = (id) => API.get(`/posts/global`);

export const signIn = (formData) => API.post('/user/signin', formData);
export const signUp = (formData) => API.post('/user/signup', formData);
export const wasd = (formData) => API.post('/user/wasd', formData);
export const confirmationwasd = (formData) => API.post('/user/confirmationwasd', formData);
