import React, { useEffect } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { useParams } from "react-router-dom";
// import classNames from 'classnames';

import { getUserEmotes } from '../../actions/emotes';
// import useStyles from './styles';

// import Emote from '../User/Emote/Emote';
import Emotes from './Emotes/Emotes';

const Dashboard = () => {

	const dispatch = useDispatch();
	// const classes = useStyles();
	const user = JSON.parse(localStorage.getItem('profile'));

	const emote = useSelector((state) => state.user);
	const id = user?.result?.id

	useEffect(() => {
		dispatch(getUserEmotes(id));
	}, [dispatch, id]);

	console.log(emote)


	const setCurrentId = (id) => {
		console.log('setCurrentId', id)
	}
	const {tag} = useParams();

	if (!user?.result) return ('не авторизован')
  switch (tag) {
  	case 'emotes':
			return ( <Emotes setCurrentId={setCurrentId}/> );
  	default:
		  return ( 'page not found' );
	}
};

export default Dashboard;
