import React from 'react';
import { Typography } from '@material-ui/core/';
import { Link } from 'react-router-dom';
// import { useDispatch } from 'react-redux';
import classNames from 'classnames';

import useStyles from './styles';

const User = ({ u }) => {
  // const dispatch = useDispatch();
  const classes = useStyles();
  // const user = JSON.parse(localStorage.getItem('profile'));

	const url = "../users/" + u

  return (
	  <Typography component={Link} to={url} className={classNames(classes.roundedLg, classes.mx_1, classes.bgDark, classes.alignItemsCenter, classes.flexLgColumn, classes.dFlex, classes.py_4, classes.px_2, classes.my_3)} style={{width: '90px', height: '115px', color: '#cfd2da'}}>
      <img className={classes.m_2} width={56} height={56} src='https://upload.wikimedia.org/wikipedia/commons/c/cc/Icon_Pinguin_1_512x512.png' alt='alt' />
      <div className={classes.ellipsis}> {u} </div>
	  </Typography>
  );
};

export default User;
