import React, { useEffect } from 'react';
import { Grid, CircularProgress, Container, Grow } from '@material-ui/core';
import { useDispatch, useSelector } from 'react-redux';

import { getGlobalEmotes } from '../../actions/emotes';

import Emote from '../User/Emote/Emote';
import useStyles from './styles';

const Emotes = ({ setCurrentId }) => {
	const dispatch = useDispatch();

  const emotes = useSelector((state) => state.user);
  const classes = useStyles();

	useEffect(() => {
		dispatch(getGlobalEmotes());
	}, [dispatch]);

  return (
		<Grow in>
      <Container>
        <Grid container justify="space-between" alignItems="stretch" spacing={3}>
          <Grid item xs={12} sm={7}>
            
				    {!emotes.length ? <CircularProgress /> : (
				      <Grid className={classes.container} container alignItems="stretch" spacing={3}>
				        {emotes.map((emote) => (
				          <Emote key={emote._id} emote={emote} setCurrentId={setCurrentId} />
				        ))}
				      </Grid>
				    )}

          </Grid>
        </Grid>
      </Container>
    </Grow>

  );
};

export default Emotes;
