import React, { useEffect } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { useParams } from "react-router-dom";
import { CircularProgress } from '@material-ui/core';

// import User from './User/User';
import Edit from './Edit/Edit';
import EmoteData from './EmoteData/EmoteData';

// import ThumbUpAltIcon from '@material-ui/icons/ThumbUpAlt';
// import ThumbUpAltOutlined from '@material-ui/icons/ThumbUpAltOutlined';


import { getEmote } from '../../actions/emotes';
import useStyles from './styles';

const Emote = () => {

  const dispatch = useDispatch();
  const classes = useStyles();
  const user = JSON.parse(localStorage.getItem('profile'));

	const emote = useSelector((state) => state.emote);
  const {id} = useParams();

	useEffect(() => {
    dispatch(getEmote(id)); // eslint-disable-next-line
  }, [dispatch]);

  if (!emote) return ('error find emote')

  // const Likes = () => {
  //   if (emote?.likes?.length > 0) {

  //     return emote.likes.find((like) => like === user?.result?.id)
  //       ? (
  //         <><ThumbUpAltIcon fontSize="small" />&nbsp;{emote.likes.length > 2 ? `You and ${emote.likes.length - 1} others` : `${emote.likes.length} like${emote.likes.length > 1 ? 's' : ''}` }</>
  //       ) : (
  //         <><ThumbUpAltOutlined fontSize="small" />&nbsp;{emote.likes.length} {emote.likes.length === 1 ? 'Like' : 'Likes'}</>
  //       );
  //   }

  //   return <><ThumbUpAltOutlined fontSize="small" />&nbsp;Like</>;
  // };

  return (
		<div className={classes.row}>
      {!emote?.likes ? <CircularProgress /> : ( <EmoteData />  )}
      {user?.result?.id === emote.user?._id ? <Edit /> : '' }
		</div>
  );
};

export default Emote;
