import React, { useState, useEffect } from 'react';
import { AppBar, Typography, Toolbar, Avatar, Button } from '@material-ui/core';
import { Link, useHistory, useLocation } from 'react-router-dom';
import { useDispatch } from 'react-redux';
import decode from 'jwt-decode';

import memories from '../../images/memories.png';
import * as actionType from '../../constants/actionTypes';
import useStyles from './styles';

const Navbar = () => {
  const [user, setUser] = useState(JSON.parse(localStorage.getItem('profile')));
  const dispatch = useDispatch();
  const location = useLocation();
  const history = useHistory();
  const classes = useStyles();

  const logout = () => {
    dispatch({ type: actionType.LOGOUT });

    history.push('/auth');

    setUser(null);
  };

  useEffect(() => {
    const token = user?.token;
    if (token) {
      const decodedToken = decode(token);

      if (decodedToken.exp * 1000 < new Date().getTime()) logout(); 
      // console.log(decodedToken)
    }

    setUser(JSON.parse(localStorage.getItem('profile')));
    console.log(JSON.parse(localStorage.getItem('profile'))) // eslint-disable-next-line
  }, [location]);

  console.log(user)

  return (
    <AppBar className={`${classes.appBar} ${classes.medquesm} ${classes.medquexs}`}   position="static" color="inherit">
      <div className={classes.brandContainer}>
        <Typography component={Link} to="/" className={classes.heading} variant="h2" align="center"> Beta </Typography>
        <Typography component={Link} to="/dashboard/emotes" className={classes.heading} variant="h2" align="center"> dashboard </Typography>
        <img className={classes.image} src={memories} alt="icon" height="60" />
      </div>
      <Toolbar className={`${classes.toolbar} ${classes.centerSignIn}` }>
        {user?.result ? (
          <div className={`${classes.profile} ${classes.center}`}>
            <Avatar className={classes.purple} alt={user.result?.user_login} src={user.result?.channel_image}>{user.result?.user_login?.charAt(0)}</Avatar>
            <Typography className={classes.userName} variant="h6">{user.result?.user_login}</Typography>
            <Button variant="contained" className={classes.logout} color="secondary" onClick={logout}>Выйти</Button>
          </div>
        ) : (
          <Button className={classes.center} component={Link} to="/auth" variant="contained" color="primary">Войти</Button>
        )}
      </Toolbar>
    </AppBar>
  );
};

export default Navbar;
