import { FETCH_ALL, CREATE, UPDATE, DELETE, LIKE, GET, USER } from '../constants/actionTypes';
import * as api from '../api/index.js';

export const getEmotes = () => async (dispatch) => {
  try {
    const { data } = await api.fetchEmotes();

    dispatch({ type: FETCH_ALL, payload: data });
  } catch (error) {
    console.log(error);
  }
};

export const createEmote = (emote) => async (dispatch) => {
  try {
    const { data } = await api.createEmote(emote);

    dispatch({ type: CREATE, payload: data });
  } catch (error) {
    console.log(error);
  }
};

export const updateEmote = (id, emote) => async (dispatch) => {
  try {
    const { data } = await api.updateEmote(id, emote);

    dispatch({ type: UPDATE, payload: data });
  } catch (error) {
    console.log(error);
  }
};

export const likeEmote = (id) => async (dispatch) => {
  const user = JSON.parse(localStorage.getItem('profile'));

  try {
    const { data } = await api.likeEmote(id, user?.token);

    dispatch({ type: LIKE, payload: data });
  } catch (error) {
    console.log(error);
  }
};

export const deleteEmote = (id) => async (dispatch) => {
  try {
    await await api.deleteEmote(id);

    dispatch({ type: DELETE, payload: id });
  } catch (error) {
    console.log(error);
  }
};

export const getEmote = (id) => async (dispatch) => {
  try {
    const { data } = await api.getEmote(id);

    dispatch({ type: GET, payload: data });
  } catch (error) {
    console.log(error);
  }
};

export const getUserEmotes = (id) => async (dispatch) => {
  try {
    const { data } = await api.getUserEmotes(id);

    dispatch({ type: USER, payload: data });
  } catch (error) {
    console.log(error);
  }
};

export const getGlobalEmotes = () => async (dispatch) => {
  try {
    const { data } = await api.getGlobalEmotes();

    dispatch({ type: USER, payload: data });
  } catch (error) {
    console.log(error);
  }
};